            if protocol.get("total_duration", 0) <= max_minutes
        ]

    def get_protocol_stage(self, protocol_name: str, elapsed_minutes: float) -> dict:
        """Get the current stage of a protocol based on elapsed time"""
        protocol = self.protocols.get(protocol_name)
        if not protocol:
            return {}

        stages = protocol.get("stages", [])
        time_sum = 0

        for stage in stages:
            time_sum += stage["duration_minutes"]
            if elapsed_minutes < time_sum:
                return stage

        # Return last stage if beyond total duration
        return stages[-1] if stages else {}

class ConnectionManager:
    def __init__(self):
        self.active_connections: Dict[str, WebSocket] = {}

    async def connect(self, websocket: WebSocket, session_id: str):
        await websocket.accept()
        self.active_connections[session_id] = websocket
        active_sessions.add(session_id)
        logger.info(f"WebSocket connected: {session_id}")

    def disconnect(self, session_id: str):
        if session_id in self.active_connections:
            del self.active_connections[session_id]
        if session_id in active_sessions:
            active_sessions.remove(session_id)
        # Stop audio session using correct audio engine session ID
        if session_id in websocket_to_audio_session:
            audio_engine_session_id = websocket_to_audio_session[session_id]
            audio_engine.stop_session(audio_engine_session_id)
            del websocket_to_audio_session[session_id]
        logger.info(f"WebSocket disconnected: {session_id}")

    async def send_personal_message(self, message: dict, session_id: str):
        websocket = self.active_connections.get(session_id)
        if websocket:
            await websocket.send_text(json.dumps(message))

    async def send_control_message(self, message_type: str, data: dict, session_id: str):
        websocket = self.active_connections.get(session_id)
        if websocket:
            await websocket.send_text(json.dumps({
                "type": message_type,
                "data": data,
                "timestamp": asyncio.get_event_loop().time()
            }))

